// Determine which email sequence to trigger
const input = $input.item.json;
const sequenceType = input.sequence_type || 'new_lead';

const sequences = {
  new_lead: {
    name: 'Bienvenue - Cours Decouverte',
    emails: [
      { day: 0, subject: 'Bienvenue dans la communaute wellness!', type: 'welcome', delay_hours: 0 },
      { day: 1, subject: 'Pourquoi le Pilates va changer ta vie', type: 'educate', delay_hours: 24 },
      { day: 3, subject: 'Ce que nos membres disent...', type: 'social_proof', delay_hours: 72 },
      { day: 5, subject: 'Ton cours decouverte t\'attend', type: 'offer', delay_hours: 120 },
      { day: 7, subject: 'Derniere chance - Cours decouverte offert', type: 'urgency', delay_hours: 168 }
    ]
  },
  post_trial: {
    name: 'Post Cours Decouverte',
    emails: [
      { day: 0, subject: 'Comment c\'etait ton premier cours?', type: 'feedback', delay_hours: 4 },
      { day: 2, subject: 'Ton corps te remercie deja', type: 'benefits', delay_hours: 48 },
      { day: 5, subject: 'Offre speciale membership - juste pour toi', type: 'membership_offer', delay_hours: 120 },
      { day: 10, subject: 'On a garde ta place...', type: 'last_chance', delay_hours: 240 }
    ]
  },
  new_member: {
    name: 'Onboarding Nouveau Membre',
    emails: [
      { day: 0, subject: 'Bienvenue dans le club! Voici ton guide', type: 'onboard_welcome', delay_hours: 0 },
      { day: 1, subject: 'Comment tirer le max de ton membership', type: 'onboard_tips', delay_hours: 24 },
      { day: 3, subject: 'As-tu essaye notre cours Reformer?', type: 'onboard_explore', delay_hours: 72 },
      { day: 7, subject: 'Ta premiere semaine - bravo!', type: 'onboard_celebrate', delay_hours: 168 },
      { day: 14, subject: 'Le prochain evenement parfait pour toi', type: 'onboard_event', delay_hours: 336 },
      { day: 30, subject: 'Un mois deja! Comment tu te sens?', type: 'onboard_checkin', delay_hours: 720 }
    ]
  },
  inactive: {
    name: 'Reengagement Membre Inactif',
    emails: [
      { day: 0, subject: 'Tu nous manques...', type: 'miss_you', delay_hours: 0 },
      { day: 3, subject: 'Un nouveau cours qui pourrait te plaire', type: 'new_offering', delay_hours: 72 },
      { day: 7, subject: 'Offre speciale pour ton retour', type: 'comeback_offer', delay_hours: 168 }
    ]
  },
  event_promo: {
    name: 'Promotion Evenement',
    emails: [
      { day: 0, subject: 'Save the date - {{ event_name }}', type: 'event_announce', delay_hours: 0 },
      { day: 7, subject: 'Plus que quelques places - {{ event_name }}', type: 'event_reminder', delay_hours: 168 },
      { day: 13, subject: 'C\'est demain! Es-tu pret(e)?', type: 'event_eve', delay_hours: 312 }
    ]
  }
};

const selectedSequence = sequences[sequenceType] || sequences.new_lead;
const currentEmail = selectedSequence.emails[input.email_index || 0];

return {
  json: {
    ...input,
    sequence: selectedSequence,
    current_email: currentEmail,
    sequence_type: sequenceType,
    total_emails: selectedSequence.emails.length,
    current_index: input.email_index || 0
  }
};

