parameters.jsCode:
const input = $('Select Email Sequence').item.json;
const aiResponse = $input.item.json.message.content;
let email;
try { email = JSON.parse(aiResponse); } catch (e) { email = { subject: input.current_email.subject, html_body: aiResponse }; }

return {
  json: {
    to: input.email,
    subject: email.subject,
    preview_text: email.preview_text,
    html_body: email.html_body,
    plain_text: email.plain_text,
    cta_text: email.cta_text,
    cta_url: email.cta_url,
    sequence_type: input.sequence_type,
    email_index: input.current_index,
    lead_id: input.lead_id || input.sender_id,
    agent_id: 'email-marketer',
    workflow_id: 'WF-EMAIL-SEQUENCE'
  }
};
